style.css:
@-moz-document domain("aosr.powerschool.com") {
/* ==============================================
   POWERSCHOOL ULTIMATE RGB GAMING THEME
   FULL CYBER RGB REDESIGN
   Made for Stylish
   ============================================== */

/* RGB COLOR VARIABLES */
:root {
    --bg: #070811;
    --panel: #101426;
    --panel2: #171d35;
    --cyan: #00f5ff;
    --purple: #a855ff;
    --pink: #ff35c7;
    --blue: #287bff;
    --green: #00ff9d;
    --text: #ecf4ff;
}

/* GLOBAL */
* {
    box-sizing: border-box;
}

html {
    background: var(--bg) !important;
}

body {
    background:
        radial-gradient(ellipse at 10% 10%, #15204b 0%, transparent 40%),
        radial-gradient(ellipse at 90% 80%, #351044 0%, transparent 40%),
        #070811 !important;
    color: var(--text) !important;
    font-family: "Segoe UI", Arial, sans-serif !important;
}

/* ANIMATED RGB BORDER */
@keyframes rgbBorder {
    0% { border-color: #00f5ff; }
    25% { border-color: #a855ff; }
    50% { border-color: #ff35c7; }
    75% { border-color: #287bff; }
    100% { border-color: #00f5ff; }
}

/* RGB TEXT GLOW */
@keyframes rgbGlow {
    0% { text-shadow: 0 0 5px #00f5ff; }
    33% { text-shadow: 0 0 10px #a855ff; }
    66% { text-shadow: 0 0 10px #ff35c7; }
    100% { text-shadow: 0 0 5px #00f5ff; }
}

/* MAIN LAYOUT */
#container,
#content,
#main,
.main-content,
.page-content,
.main,
.content,
#mainContent {
    background: transparent !important;
    color: var(--text) !important;
}

/* HEADER */
header,
#header,
.navbar,
.navigation,
.site-header {
    background: linear-gradient(
        110deg,
        #080c1c,
        #15102b,
        #101a36
    ) !important;
    border-bottom: 2px solid var(--cyan) !important;
    box-shadow: 0 4px 25px #00cfff44 !important;
}

/* NAVIGATION */
nav,
nav ul,
.navbar,
.navigation {
    background-color: #0d1224 !important;
}

nav a,
.navbar a,
.navigation a,
header a {
    color: #00eaff !important;
    font-weight: 600 !important;
    transition: 0.3s ease !important;
}

nav a:hover,
.navbar a:hover,
.navigation a:hover {
    color: #ffffff !important;
    text-shadow:
        0 0 5px #00f5ff,
        0 0 15px #a855ff !important;
}

/* PANELS AND CARDS */
.panel,
.card,
.well,
.portlet,
.box,
.panel-default,
.panel-heading,
.panel-body {
    background: #11172b !important;
    color: var(--text) !important;
    border: 1px solid #26365b !important;
    border-radius: 12px !important;
    box-shadow: 0 0 15px #006aff22 !important;
    transition: 0.3s ease !important;
}

.panel:hover,
.card:hover,
.portlet:hover {
    border-color: var(--purple) !important;
    box-shadow: 0 0 18px #a855ff44 !important;
}

/* HEADINGS */
h1, h2, h3, h4, h5 {
    color: #00eaff !important;
    font-weight: 700 !important;
    animation: rgbGlow 6s infinite alternate !important;
}

/* BUTTONS */
button,
.btn,
input[type="button"],
input[type="submit"],
.button {
    background: linear-gradient(
        120deg,
        #006dff,
        #773cff,
        #d42cff
    ) !important;
    color: white !important;
    border: 1px solid #00eaff !important;
    border-radius: 8px !important;
    font-weight: bold !important;
    padding: 9px 17px !important;
    box-shadow: 0 0 12px #633cff66 !important;
    transition: all 0.25s ease !important;
}

button:hover,
.btn:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
.button:hover {
    transform: translateY(-3px) scale(1.02) !important;
    box-shadow:
        0 0 10px #00eaff,
        0 0 25px #a855ff !important;
    filter: brightness(1.25) !important;
}

/* TABLES */
table {
    background: #101629 !important;
    color: white !important;
    border-collapse: separate !important;
    border-spacing: 0 !important;
    border-radius: 10px !important;
    overflow: hidden !important;
    border: 1px solid #263d69 !important;
}

thead,
th {
    background: linear-gradient(
        100deg,
        #112b50,
        #29204d
    ) !important;
    color: #00f5ff !important;
    text-transform: uppercase !important;
    letter-spacing: 1px !important;
}

td, th {
    border-color: #293657 !important;
    padding: 11px !important;
}

tr:nth-child(even) {
    background: #151d35 !important;
}

tr:hover {
    background: #252347 !important;
    box-shadow: inset 0 0 10px #00eaff33 !important;
}

/* GRADE COLORS */
.gradeA, .grade-a {
    color: #00ff9d !important;
    text-shadow: 0 0 10px #00ff9d77 !important;
    font-weight: bold !important;
}

.gradeB, .grade-b {
    color: #00eaff !important;
    font-weight: bold !important;
}

.gradeC, .grade-c {
    color: #ffe66d !important;
    font-weight: bold !important;
}

.gradeD, .grade-d {
    color: #ff9d4d !important;
    font-weight: bold !important;
}

.gradeF, .grade-f {
    color: #ff4267 !important;
    text-shadow: 0 0 10px #ff426777 !important;
    font-weight: bold !important;
}

/* LINKS */
a {
    color: #00d9ff !important;
    transition: 0.2s ease !important;
}

a:hover {
    color: #ff35c7 !important;
    text-shadow: 0 0 9px #ff35c7 !important;
}

/* INPUTS */
input,
select,
textarea {
    background: #090f20 !important;
    color: white !important;
    border: 1px solid #344d80 !important;
    border-radius: 7px !important;
    padding: 8px !important;
}

input:focus,
select:focus,
textarea:focus {
    outline: none !important;
    border-color: #00eaff !important;
    box-shadow: 0 0 12px #00eaff77 !important;
}

/* DROPDOWNS */
.dropdown-menu {
    background: #11172b !important;
    border: 1px solid #a855ff !important;
    box-shadow: 0 0 18px #a855ff44 !important;
}

.dropdown-menu a {
    color: white !important;
}

.dropdown-menu a:hover {
    background: #252347 !important;
}

/* GRADE PROGRESS BARS */
.progress,
.progress-bar {
    background-color: #18223b !important;
    border-radius: 20px !important;
}

.progress-bar {
    background: linear-gradient(
        90deg,
        #00eaff,
        #a855ff,
        #ff35c7
    ) !important;
    box-shadow: 0 0 12px #00eaff88 !important;
}

/* ALERTS */
.alert,
.notification {
    background: #151d35 !important;
    color: white !important;
    border: 1px solid #00eaff !important;
    border-radius: 9px !important;
}

/* SIDEBAR */
aside,
.sidebar,
#sidebar {
    background: #0c1122 !important;
    color: white !important;
    border-right: 1px solid #26365b !important;
}

aside a,
.sidebar a,
#sidebar a {
    color: #00d9ff !important;
}

aside a:hover,
.sidebar a:hover {
    background: #242044 !important;
}

/* FOOTER */
footer,
#footer {
    background: #090d1b !important;
    color: #8499bc !important;
    border-top: 1px solid #a855ff !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {
    background: #080b16;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(
        180deg,
        #00eaff,
        #a855ff,
        #ff35c7
    );
    border-radius: 20px;
}

/* TEXT SELECTION */
::selection {
    background: #a855ff;
    color: white;
}

/* CHECKBOXES */
input[type="checkbox"],
input[type="radio"] {
    accent-color: #a855ff !important;
}

/* IMAGES */
img {
    border-radius: 6px;
}

/* REMOVE UNWANTED LIGHT BACKGROUNDS */
.bg-white,
.white,
.wbg,
[style*="background-color: white"],
[style*="background-color: #fff"] {
    background-color: #11172b !important;
    color: white !important;
}

/* FINAL SMOOTH EFFECTS */
a, button, .btn, .panel, .card {
    transition: all 0.25s ease !important;
}

/* REDUCE MOTION FOR ACCESSIBILITY */
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation: none !important;
        transition: none !important;
    }
}

/* ==============================================
   END OF ULTIMATE RGB POWERSCHOOL THEME
   ============================================== */
}
